+ * DS4_THINK_MAX rendered the "high" text above instead. Note the em dash (U+2014)
+ * right after "Beyond maximum" -- verified byte-for-byte against the primary source. */
+static const char DS4_REASONING_EFFORT_MAX_PREFIX[] =
